// Vulnerable: Using reflection to access private methods
class VulnerableClass {
    private int secretValue;

    public void setSecret(int value) {
        secretValue = value;
    }

    public int getSecret() {
        return secretValue;
    }
}

public class VulnerableDemo {
    public static void main(String[] args) {
        VulnerableClass obj = new VulnerableClass();
        // Using reflection to access private method
        java.lang.reflect.Method setMethod = VulnerableClass.class.getDeclaredMethod("setSecret", int.class);
        setMethod.setAccessible(true);
        setMethod.invoke(obj, 42);
        System.out.println("Secret value set to: " + obj.getSecret());
    }
}
