// Fixed: Using proper API and input validation
class SecureClass {
    private int secretValue;

    public void setSecret(int value) {
        // Validate input
        if (value < 0 || value > 1000) {
            throw new IllegalArgumentException("Secret value must be between 0 and 1000");
        }
        secretValue = value;
    }

    public int getSecret() {
        return secretValue;
    }
}

public class SecureDemo {
    public static void main(String[] args) {
        SecureClass obj = new SecureClass();
        // Using proper API with validation
        obj.setSecret(42);
        System.out.println("Secret value set to: " + obj.getSecret());
    }
}
